import {models,offers,shops,categories,regions,model,shop,money,shipping} from './data.js';
import {db,tx,user,mine,uid,addItems,currentOffer} from './store.js';
import {esc,params,link,go,a,button,field,select,textarea,submit,form,notice,empty,panel,head,mount,toast,dialog,requireUser} from './ui.js';
const price=m=>Math.min(...offers.filter(o=>o.modelId===m.id&&currentOffer(o.id).active).map(o=>currentOffer(o.id).price));
const context=()=>Object.fromEntries(['slot','build','version'].filter(k=>params.has(k)).map(k=>[k,params.get(k)]));
const catalogueLink=m=>link('model',{id:m.id,...context(),...(location.pathname.endsWith('/search.html')?{from:params.toString()}: {})});
const available=m=>offers.filter(o=>o.modelId===m.id).map(o=>currentOffer(o.id)).filter(o=>o.active&&shop(o.shopId).active);
const priceText=m=>available(m).length?money(price(m)):'Chưa có offer đang bán';
export function card(m){const os=offers.filter(o=>o.modelId===m.id&&currentOffer(o.id).active);return '<article class="catalog-card"><a class="catalog-visual" href="'+catalogueLink(m)+'" aria-label="'+esc(m.name)+'"><span>'+m.category+'</span><small>'+esc(Object.values(m.specs).slice(0,2).join(' · '))+'</small></a><div class="catalog-body"><p class="muted">'+esc(categories[m.category])+'</p><h3><a href="'+catalogueLink(m)+'">'+esc(m.name)+'</a></h3><p class="muted">'+esc(Object.values(m.specs).slice(0,3).join(' · '))+'</p><div class="catalog-price"><small>Giá demo từ</small><strong>'+priceText(m)+'</strong><span>'+os.length+' shop bán</span></div><div class="cluster"><a class="btn btn--primary" href="'+catalogueLink(m)+'">Chọn shop</a>'+button('So sánh','compare-add',m.id)+'</div></div></article>';}
export function home(){mount('Mua linh kiện',head('Linh kiện cho chiếc PC của bạn.','Chọn sản phẩm, so sánh giá và điều kiện từ từng shop.',a('Khám phá linh kiện','search',{},'primary'))+'<nav class="category-strip" aria-label="Danh mục">'+Object.entries(categories).map(([k,v])=>'<a href="'+link('search',{category:k})+'"><strong>'+k+'</strong><span>'+v+'</span></a>').join('')+'</nav><section><div class="section-heading"><h2>Khám phá linh kiện</h2>'+a('Xem tất cả '+models.length+' model','search')+'</div><div class="catalog-grid">'+[models[0],models[7],models[5],models[9]].map(card).join('')+'</div></section><section class="build-entry"><div><h2>Cần chọn cả cấu hình?</h2><p>Tự chọn từng linh kiện hoặc gửi nhu cầu để shop đề xuất.</p></div><div class="cluster">'+a('Tự build PC','builder')+a('Build theo ngân sách','requests',mine('requests').length?{}:{new:'1'})+'</div></section><section><div class="section-heading"><h2>Gian hàng trên PCMatch</h2></div><div class="shop-strip">'+shops.map(s=>'<a href="'+link('shop',{id:s.id})+'"><strong>'+esc(s.name)+'</strong><span>'+regions[s.region]+' · '+(s.active?'Đang bán (demo)':'Tạm ngừng bán')+'</span></a>').join('')+'</div></section>');}
export function search(){
 if(params.get('error')==='1'){mount('Tìm kiếm',head('Tìm linh kiện')+empty('Chưa tải được danh mục','Lỗi tải mô phỏng. Bộ lọc vẫn được giữ.',button('Thử lại','search-retry')));return;}
 const cat=params.get('slot')||params.get('category')||'',q=params.get('q')||'',brand=params.get('brand')||'',spec=params.get('spec')||'',min=Number(params.get('min')||0),max=Number(params.get('max')||Infinity);
 let list=models.filter(m=>(!cat||m.category===cat)&&(!q||m.name.toLowerCase().includes(q.toLowerCase()))&&(!brand||m.brand===brand)&&(!spec||Object.values(m.specs).includes(spec))&&price(m)>=min&&price(m)<=max&&(!params.has('stock')||offers.some(o=>o.modelId===m.id&&currentOffer(o.id).stock>0&&currentOffer(o.id).active)));
 if(params.get('sort')==='price')list.sort((a,b)=>price(a)-price(b));if(params.get('sort')==='desc')list.sort((a,b)=>price(b)-price(a));
 const pages=Math.max(1,Math.ceil(list.length/6)),p=Math.min(pages,Math.max(1,Number(params.get('p'))||1));
 const specs=Object.fromEntries([...new Set(models.filter(m=>m.category===cat).flatMap(m=>Object.values(m.specs)))].map(x=>[x,x]));
 const fields=field('Từ khóa','q',q)+select('Danh mục','category',{'':'Tất cả',...categories},cat,params.has('slot')?'disabled':'')+select('Hãng','brand',{'':'Tất cả',...Object.fromEntries([...new Set(models.filter(m=>!cat||m.category===cat).map(m=>m.brand))].map(x=>[x,x]))},brand)+field('Giá từ (₫)','min',params.get('min')||'','number','min="0" step="1"')+field('Giá đến (₫)','max',params.get('max')||'','number','min="0" step="1"')+select('Thông số theo danh mục','spec',{'':'Tất cả',...specs},spec)+select('Sắp xếp','sort',{'':'Theo danh mục',price:'Giá tăng dần',desc:'Giá giảm dần'},params.get('sort'))+'<label class="check"><input type="checkbox" name="stock" '+(params.has('stock')?'checked':'')+'> Còn hàng</label>'+submit('Áp dụng bộ lọc');
 mount('Tìm linh kiện',head(params.has('slot')?'Chọn '+categories[cat]:'Tìm linh kiện',list.length+' model phù hợp trong dữ liệu demo',a('So sánh ('+db().compare.length+')','compare')+(params.has('slot')?a('Về cấu hình','builder'):''))+'<div class="search-layout"><details class="filters" open><summary>Bộ lọc tìm kiếm</summary>'+form('filters',fields)+'</details><section><div class="cluster filter-chips">'+[...params.entries()].filter(([k])=>['q','brand','category','spec','min','max','stock'].includes(k)).map(([k,v])=>button(esc(k+': '+(v||'Có'))+' ×','remove-filter',k)).join('')+a('Xóa bộ lọc','search',context())+'</div><div class="catalog-grid results">'+list.slice((p-1)*6,p*6).map(card).join('')+'</div>'+(!list.length?empty('Không có kết quả','Thử bỏ bớt điều kiện hoặc đổi từ khóa.',a('Xóa bộ lọc','search',context())):'')+'<nav class="pagination" aria-label="Phân trang">'+(p>1?a('Trước','search',{...Object.fromEntries(params),p:p-1}):'')+'<span>Trang '+p+' / '+pages+'</span>'+(p<pages?a('Tiếp','search',{...Object.fromEntries(params),p:p+1}):'')+'</nav>'+a('Thử lỗi tải demo','search',{...Object.fromEntries(params),error:'1'},'quiet')+'</section></div>');
}
export function detail(){
 const m=model(params.get('id'));if(!m){mount('Model',empty('Không tìm thấy model','Chọn một model từ danh mục.'));return;}
 const region=params.get('region')||'HCM',selected=params.get('shop'),os=offers.filter(o=>o.modelId===m.id).map(o=>currentOffer(o.id)).sort((a,b)=>Number(b.shopId===selected)-Number(a.shopId===selected));
 mount(m.name,head(m.name,'Model '+m.id+' · Thông số minh họa, cần đối chiếu hãng',a('Về kết quả tìm kiếm','search',params.has('from')?Object.fromEntries(new URLSearchParams(params.get('from'))):{category:m.category,...context()})+button('So sánh model','compare-add',m.id))+'<div class="model-overview"><div class="catalog-visual large"><span>'+m.category+'</span><small>'+esc(m.brand)+'</small></div><div><h2>'+priceText(m)+' <small>giá từ</small></h2><p>'+esc(m.description)+'</p><dl class="spec-grid">'+Object.entries(m.specs).map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl>'+notice('Bộ thông số là dữ liệu kiểm thử, không phải chứng nhận tương thích. Nguồn fixture: <a href="../assets/js/data.js">catalogue demo</a>. Tra cứu thông số chính thức trên website của hãng trước khi mua.')+'</div></div><section id="offers"><div class="section-heading"><h2>So sánh '+os.length+' offer</h2>'+form('region',select('Khu vực nhận','region',regions,region)+submit('Cập nhật phí'))+'</div><div class="offer-cards">'+os.map(o=>'<article id="offer-'+o.id+'" class="offer-card'+(o.shopId===selected?' offer-selected':'')+'"><div>'+(o.shopId===selected?'<p><strong>Offer từ gian hàng bạn chọn</strong></p>':'')+'<h3><a href="'+link('shop',{id:o.shopId})+'">'+shop(o.shopId).name+'</a></h3><p>'+o.id+'</p><p>'+(()=>{const rs=db().reviews.filter(r=>r.shopId===o.shopId);return rs.length?(rs.reduce((n,r)=>n+r.shopRating,0)/rs.length).toFixed(1)+'/5 · '+rs.length+' đánh giá shop trong demo':'Chưa có đánh giá shop trong demo';})()+'</p><strong class="price">'+money(o.price)+'</strong><p>'+(!o.active?'Tạm ngừng bán':o.stock?'Còn '+o.stock+' (demo)':'Hết hàng')+'</p></div><div><p>Bảo hành '+o.warranty+' tháng · Tiếp nhận tại '+shop(o.shopId).name+'</p><p>'+esc(o.accessories)+'</p><p>Tổng một món + giao: '+(shipping(o.shopId,region)===null?'Chưa tính được':money(o.price+shipping(o.shopId,region)))+'</p><p>Giao ước tính '+(shipping(o.shopId,region)===null?'chưa hỗ trợ':money(shipping(o.shopId,region)))+' · 3–5 ngày (demo)</p><details><summary>Điều kiện bán và bảo hành</summary><p>Hàng mới. Shop tiếp nhận kiểm tra lỗi, không cam kết tự động đổi/hoàn. Điều khoản này được chụp vào đơn demo.</p></details></div>'+form('offer', '<input type="hidden" name="offerId" value="'+o.id+'">'+field('Số lượng','qty',1,'number','required min="1" max="'+o.stock+'" step="1"')+select('Thao tác','target',{cart:'Thêm vào giỏ',build:'Thêm vào cấu hình'},params.has('slot')?'build':'cart')+'<button type="submit" class="btn btn--primary" '+(!o.active||!shop(o.shopId).active||!o.stock?'disabled':'')+'>Chọn offer này</button>')+'</article>').join('')+'</div></section>'+panel('Hỏi đáp trước mua',db().questions.filter(x=>x.modelId===m.id).map(x=>'<article class="list-row"><div><strong>'+esc(x.text)+'</strong><p>'+shop(x.shopId).name+' · '+esc(x.reply||'Chưa có trả lời')+'</p></div></article>').join('')+form('question',select('Shop nhận câu hỏi','shopId',Object.fromEntries(os.map(o=>[o.shopId,shop(o.shopId).name])))+textarea('Câu hỏi (không ghi số điện thoại/địa chỉ)','text')+submit('Gửi câu hỏi')))+panel('Đánh giá sau mua',db().reviews.filter(r=>r.modelId===m.id).map(r=>'<p><strong>Đã mua trong demo · Sản phẩm '+r.productRating+'/5 · Shop '+r.shopRating+'/5</strong><br>'+esc(r.text)+'</p>').join('')||'<p>Chưa có đánh giá. Chỉ dòng hàng đã giao mới được viết đánh giá.</p>')+a('Báo cáo nội dung sản phẩm','cases',{new:'report',target:m.id}));
}
export function storefront(){
 const s=shop(params.get('id'));if(!s){mount('Gian hàng',empty('Không tìm thấy shop','Mở shop từ trang sản phẩm.'));return;}
 const q=params.get('q')||'',list=offers.filter(o=>o.shopId===s.id&&model(o.modelId).name.toLowerCase().includes(q.toLowerCase())).map(o=>currentOffer(o.id)),reviews=db().reviews.filter(r=>r.shopId===s.id);
 mount(s.name,head(s.name,regions[s.region]+' · 09:00–18:00 (minh họa)',a('Báo cáo shop','cases',{new:'report',target:s.id}))+notice(s.active?'Gian hàng demo. Chưa xác minh thực tế.':'Shop tạm ngừng bán. Đơn cũ vẫn được gửi yêu cầu hỗ trợ.',s.active?'info':'warn')+panel('Thông tin gian hàng','<p>Chuyên linh kiện mới. Bảo hành tiếp nhận tại shop, điều kiện theo từng offer. Lắp ráp chỉ khi shop cung cấp đủ bộ.</p>'+(s.consult&&s.active?a('Gửi cấu hình đang chọn để tư vấn','consultation',{new:1,shop:s.id}):'')+a('Hỗ trợ đơn đã mua','orders'))+panel('Đánh giá dịch vụ shop',reviews.length?'<p>'+reviews.length+' đánh giá sau mua demo · Trung bình '+(reviews.reduce((n,r)=>n+r.shopRating,0)/reviews.length).toFixed(1)+'/5</p>'+reviews.map(r=>'<p>'+r.shopRating+'/5 · '+esc(r.text)+'</p>').join(''):'<p>Chưa có đánh giá sau mua trong demo.</p>')+form('shop-filter',field('Tìm trong shop','q',q)+submit('Lọc sản phẩm'))+(list.length?'<div class="catalog-grid">'+list.map(o=>'<article class="catalog-card"><div class="catalog-body"><h3>'+esc(model(o.modelId).name)+'</h3><p class="price">'+money(o.price)+'</p><p>'+(!s.active||!o.active?'Tạm ngừng bán':o.stock?'Còn '+o.stock+' (demo)':'Hết hàng')+' · BH '+o.warranty+' tháng</p>'+a('Xem offer của shop','model',{id:o.modelId,shop:s.id})+'</div></article>').join('')+'</div>':empty('Không có sản phẩm phù hợp','Đổi từ khóa hoặc xem toàn bộ gian hàng.',a('Xóa tìm kiếm','shop',{id:s.id}))));
}
export function compare(){const ms=db().compare.map(model).filter(Boolean);mount('So sánh linh kiện',head('So sánh linh kiện','Chọn tối đa 4 model cùng danh mục',button('Xóa danh sách','compare-clear'))+(!ms.length?empty('Chưa chọn model','Thêm model từ kết quả tìm kiếm.'): '<div class="table-wrap" tabindex="0" aria-label="Bảng so sánh cuộn ngang"><table class="data-table"><thead><tr><th>Thông số</th>'+ms.map(m=>'<th>'+esc(m.name)+button('Bỏ','compare-remove',m.id)+'</th>').join('')+'</tr></thead><tbody>'+['Giá từ',...new Set(ms.flatMap(m=>Object.keys(m.specs)))].map(k=>'<tr><th>'+esc(k)+'</th>'+ms.map(m=>'<td>'+(k==='Giá từ'?priceText(m):esc(m.specs[k]||'Chưa có dữ liệu'))+'</td>').join('')+'</tr>').join('')+'<tr><th>Offer</th>'+ms.map(m=>'<td>'+a('Chọn shop','model',{id:m.id})+'</td>').join('')+'</tr></tbody></table></div>'));}
export function action(act,id){
 if(act==='search-retry'||act==='remove-filter'){const p=new URLSearchParams(params);p.delete(act==='search-retry'?'error':id);if(act==='remove-filter')p.delete('p');go('search',Object.fromEntries(p));return true;}
 if(act==='compare-add'){const m=model(id),chosen=db().compare.map(model);if(chosen.some(x=>x.category!==m.category))throw Error('Chỉ so sánh model cùng loại. Hãy xóa danh sách so sánh trước.');if(!db().compare.includes(id)){if(chosen.length>=4)throw Error('Tối đa 4 model.');tx(s=>s.compare.push(id));}toast('Đã thêm vào so sánh. Mở “So sánh” tại trang tìm kiếm.');return true;}
 if(act==='compare-clear'||act==='compare-remove'){tx(s=>s.compare=act==='compare-clear'?[]:s.compare.filter(x=>x!==id));compare();return true;}return false;
}
export async function submitForm(name,f,d){
 if(name==='filters'){if(d.max&&+d.max<+d.min)throw Error('Giá đến phải lớn hơn hoặc bằng giá từ.');go('search',{...Object.fromEntries(Object.entries(d).filter(([,v])=>v)),...context()});return true;}
 if(name==='region'){go('model',{...Object.fromEntries(params),region:d.region});return true;}
 if(name==='shop-filter'){go('shop',{id:params.get('id'),q:d.q});return true;}
 if(name==='offer'){const o=currentOffer(d.offerId),qty=Number(d.qty);if(d.target==='cart'){const put=()=>{addItems([{offerId:o.id,qty}]);go('cart');};if(db().checkout.proposal)dialog('Chuyển giỏ proposal sang mua lẻ?','Thêm sản phẩm sẽ bỏ điều kiện lắp ráp và báo giá trọn bộ. Các món đang có được giữ.',put);else put();}else{const b=db().draftBuild,cat=model(o.modelId).category;if(params.has('slot')&&(params.get('slot')!==cat||params.get('build')!==b.id||+params.get('version')!==b.version))throw Error('Cấu hình đã đổi hoặc sai slot. Quay về Builder chọn lại.');if(!Number.isInteger(qty)||qty<1||qty>o.stock)throw Error('Số lượng không hợp lệ.');const put=()=>{tx(s=>{s.draftBuild.slots[cat]={offerId:o.id,qty,owned:false};s.draftBuild.version++;});go('builder');};if(b.slots[cat])dialog('Thay linh kiện '+cat+'?', 'Thay '+esc(model(currentOffer(b.slots[cat].offerId).modelId).name)+' bằng '+esc(model(o.modelId).name)+'. Các slot khác được giữ.',put);else put();}return true;}
 if(name==='question'){if(!requireUser())return true;if(!d.text.trim())throw Error('Nhập câu hỏi.');tx(s=>s.questions.push({id:uid('QA'),userId:user().id,modelId:params.get('id'),shopId:d.shopId,text:d.text}));detail();toast('Đã gửi câu hỏi demo.');return true;}return false;
}
